type Status = 'idle' | 'loading' | 'success' | 'error';

type AsyncState<T> = {
  status: Status;
  data?: T;
  error?: Error;
};

function DataDisplay<T>({ state }: { state: AsyncState<T> }) {
  if (state.status === 'loading') {
    return <div>Loading...</div>;
  }

  if (state.status === 'error') {
    return <div>Error: {state.error?.message}</div>;
  }

  // TypeScript knows status is 'success' and data is defined
  return <div>{JSON.stringify(state.data)}</div>;
}

// Custom type guard
function isUser(u: unknown): u is { id: number; name: string } {
  return typeof u === 'object' && u !== null && 'id' in u;
}
